use core.files as files
use core.process as process
use core.text as text
use core.encoding.json as json

struct Report {
    count: Int
    name: String
    note: String
}
fn digit_value(ch: String) Int -> {
    if ch == "0" -> return 0
    if ch == "1" -> return 1
    if ch == "2" -> return 2
    if ch == "3" -> return 3
    if ch == "4" -> return 4
    if ch == "5" -> return 5
    if ch == "6" -> return 6
    if ch == "7" -> return 7
    if ch == "8" -> return 8
    if ch == "9" -> return 9
    panic("invalid count")
}

fn parse_count(value: String) Int -> {
    if value.is_empty() -> panic("invalid count")
    total := 0
    digits :: value.split("")
    loop digit in digits {
        if digit.is_empty() -> next
        total = total * 10 + digit_value(digit)
    }
    return total
}


fn run() {
    path :: process.argv().get(1) ?? panic("missing path")
    source :: files.read(path) ?? panic("read failed")
    lines :: source.lines()
    name := ""
    count_text := ""
    note := ""
    seen_name := false
    seen_count := false
    seen_note := false

    loop line in lines {
        if line.trim().is_empty() -> next
        parts :: text.splitn(line, "\t", 3)
        if parts.len() != 2 -> panic("malformed report field")
        key_raw :: parts.get(0) ?? panic("missing report field name")
        key :: ~(key_raw.trim())
        value :: ~(parts.get(1) ?? panic("missing report field value"))
        if key == "name" {
            if seen_name -> panic("duplicate name field")
            name = value
            seen_name = true
        } else if key == "count" {
            if seen_count -> panic("duplicate count field")
            count_text = value
            seen_count = true
        } else if key == "note" {
            if seen_note -> panic("duplicate note field")
            note = value
            seen_note = true
        } else {
            panic("unknown report field {key}")
        }
    }
    if !seen_name || !seen_count || !seen_note -> panic("missing report field")
    report :: Report{count: parse_count(count_text), name: name, note: note}
    encoded_name :: json.to_string(name)
    encoded_note :: json.to_string(note)
    encoded :: "{{\"count\":{report.count},\"name\":{encoded_name},\"note\":{encoded_note}}}"
    print(encoded)
}
